import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { vec3, mix, uv, time } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const timelines = [];
  const textBlocks = [];

  // === BACKDROP PLANE WITH GRADIENT ===
  const backdropGeometry = new THREE.PlaneGeometry(7, 5.5);
  const backdropMaterial = new MeshBasicNodeMaterial();

  // TSL gradient from #0b0b10 (bottom) to #14141a (top)
  const colorA = vec3(0.043, 0.043, 0.082); // #0b0b10
  const colorB = vec3(0.078, 0.078, 0.102); // #14141a
  const gradientNode = mix(colorA, colorB, uv().y);

  // Add grain overlay via mix with noise-like pattern (1.5% monochrome)
  const grainIntensity = 0.015;
  const grainNoise = vec3(
    Math.sin(uv().x * 100 + uv().y * 50) * 0.5 + 0.5
  );
  backdropMaterial.colorNode = mix(gradientNode, grainNoise, grainIntensity);

  const backdropMesh = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.z = 0;
  group.add(backdropMesh);

  // === TEXT ELEMENTS ===
  const baseX = -3.1;

  // Kicker: "NOVA ATELIER / JOURNAL"
  const kickerMesh = ctx.fontAtlas.createText('NOVA ATELIER / JOURNAL', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'left'
  });
  kickerMesh.position.set(baseX, 1.7, 0.1);
  kickerMesh.userData.animGroup = 'kicker';
  group.add(kickerMesh);
  textBlocks.push(kickerMesh);

  // Hero line 1: "PRECISION IS"
  const heroLine1 = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left'
  });
  heroLine1.position.set(baseX, 0.9, 0.1);
  heroLine1.userData.animGroup = 'hero';
  group.add(heroLine1);
  textBlocks.push(heroLine1);

  // Hero line 1 shadow (letterpress effect)
  const heroLine1Shadow = ctx.fontAtlas.createText('PRECISION IS', {
    fontSize: 124,
    color: '#16161d',
    align: 'left'
  });
  heroLine1Shadow.position.set(baseX, 0.9, -0.02);
  group.add(heroLine1Shadow);

  // Hero line 2: "A HABIT."
  const heroLine2 = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left'
  });
  heroLine2.position.set(baseX, 0.25, 0.1);
  heroLine2.userData.animGroup = 'hero';
  group.add(heroLine2);
  textBlocks.push(heroLine2);

  // Hero line 2 shadow
  const heroLine2Shadow = ctx.fontAtlas.createText('A HABIT.', {
    fontSize: 124,
    color: '#16161d',
    align: 'left'
  });
  heroLine2Shadow.position.set(baseX, 0.25, -0.02);
  group.add(heroLine2Shadow);

  // === ACCENT UNDERLINE RULE ===
  const ruleGeometry = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.2
  });
  const ruleMesh = new THREE.Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(baseX + 1.1, -0.15, 0.05);
  ruleMesh.scale.x = 0;
  ruleMesh.userData.isRule = true;
  group.add(ruleMesh);

  // Body paragraph: "Notes from the bench..."
  const bodyMesh = ctx.fontAtlas.createText(
    'Notes from the bench: tolerances, tempering,\nand the case for slower watchmaking.',
    {
      fontSize: 26,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 800
    }
  );
  bodyMesh.position.set(baseX, -0.8, 0.1);
  bodyMesh.userData.animGroup = 'body';
  group.add(bodyMesh);
  textBlocks.push(bodyMesh);

  // Caption: "ISSUE 12 / JULY 2026"
  const captionMesh = ctx.fontAtlas.createText('ISSUE 12 / JULY 2026', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'left'
  });
  captionMesh.position.set(baseX, -1.9, 0.1);
  captionMesh.userData.animGroup = 'caption';
  group.add(captionMesh);
  textBlocks.push(captionMesh);

  // === ENTRANCE ANIMATIONS ===
  const animationGroups = {
    kicker: [kickerMesh],
    hero: [heroLine1, heroLine2],
    body: [bodyMesh],
    caption: [captionMesh]
  };

  let currentDelay = 0;
  const staggerDelay = 0.08;
  const riseInDuration = 0.7;

  // Animate each group with stagger
  const groupOrder = ['kicker', 'hero', 'body', 'caption'];
  groupOrder.forEach((groupName) => {
    animationGroups[groupName].forEach((mesh) => {
      // Store initial position
      const initY = mesh.position.y;
      mesh.position.y += 0.4;
      mesh.material.opacity = 0;

      const tl = gsap.timeline({ delay: currentDelay });
      tl.to(mesh.position, {
        y: initY,
        duration: riseInDuration,
        ease: 'power3.out'
      }, 0);
      tl.to(mesh.material, {
        opacity: 1,
        duration: riseInDuration,
        ease: 'power3.out'
      }, 0);

      timelines.push(tl);
    });

    currentDelay += staggerDelay;
  });

  // Rule animation starts after hero lands
  const ruleDelay = currentDelay - staggerDelay + riseInDuration;
  const ruleTl = gsap.timeline({ delay: ruleDelay });
  ruleTl.to(ruleMesh.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.inOut'
  }, 0);
  timelines.push(ruleTl);

  // === CLEANUP ===
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    backdropGeometry.dispose();
    backdropMaterial.dispose();
    ruleGeometry.dispose();
    ruleMaterial.dispose();
  };

  return group;
}
